import { useKeyboardControls } from '@react-three/drei'
import { useFrame, useThree } from '@react-three/fiber'
import {
  type RapierCollider,
  useAfterPhysicsStep,
  useBeforePhysicsStep,
  useRapier,
} from '@react-three/rapier'
import {
  type AvatarView,
  Dynamic,
  type PlayerControl,
  type PlayerMotion,
  PlayerMotionContext,
  type PlayerPin,
  type TeleportOptions,
  useMaterial,
  useWorld,
  type Vec3,
  type WaterSample,
  waterAt,
} from '@runek/core'
import Ecctrl, { type CustomEcctrlRigidBody, useJoystickControls } from 'ecctrl'
import {
  type ReactNode,
  type RefObject,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react'
import {
  type Camera,
  type Group,
  type Object3D,
  type PerspectiveCamera,
  type Scene,
  Vector3,
} from 'three'
import { raiseBoom, SWIM_TILT } from './player/boom'
import { PaniniLens } from './player/PaniniLens'
import {
  CLIMB_REACH,
  createSwimState,
  type SwimShape,
  stepSwim,
  submersion,
  swimming,
} from './player/swim'
import { Underwater } from './player/Underwater'
import { WaterTrail } from './water/trail'
import type { WakeBody } from './water/wake'

export type PlayerView = AvatarView

// Keyboard look. ecctrl only moves its camera from mouse/touch/gamepad — there are no key
// actions for it — so we drive its camera rig ourselves from the `turnLeft`/`turnRight` and
// `lookUp`/`lookDown` actions in the world's controls (see `DEFAULT_CONTROLS` in `@runek/core`).
// Yaw is the pivot's `rotation.y`; pitch is the follow-cam's `rotation.x` plus a matching
// reposition along a vertical arc, exactly as ecctrl's own mouse handler does — the same math
// ecctrl runs in both views, so this works first- and third-person alike. ecctrl writes these
// only on pointer input (never per frame in CameraBasedMovement), so our additions compose
// cleanly with mouse-drag. A world whose controls omit these actions leaves the camera entirely
// to the mouse.
const TURN_SPEED = 1.8 // yaw, radians/second
const LOOK_SPEED = 1.2 // pitch, radians/second
// Pitch clamp — mirrors ecctrl's camLowLimit / camUpLimit defaults (we pass neither to Ecctrl).
const CAM_LOW = -1.3
const CAM_UP = 1.5

/**
 * ecctrl's camera pivot: a bare Object3D added to the scene whose single child is the (childless)
 * follow-cam, offset back along -z by the camera distance (or -0.01 in first person). Sign and
 * shape identify it in every view without tying anything to one of them.
 */
function findPivot(scene: Scene): Object3D | null {
  return (
    scene.children.find(
      (o) =>
        o.type === 'Object3D' &&
        o.children.length === 1 &&
        o.children[0].type === 'Object3D' &&
        o.children[0].children.length === 0 &&
        o.children[0].position.x === 0 &&
        o.children[0].position.z < -0.001,
    ) ?? null
  )
}

function CameraKeyLook({ pitchable }: { pitchable: boolean }) {
  const scene = useThree((s) => s.scene)
  const [, getKeys] = useKeyboardControls()
  const pivot = useRef<Object3D | null>(null)

  useFrame((_, dt) => {
    // Cached once found; until it mounts (or if the match ever misses) mouse-drag still turns, so
    // a miss just no-ops rather than breaking.
    if (!pivot.current) {
      pivot.current = findPivot(scene)
      if (!pivot.current) return
    }
    const step = Math.min(dt, 0.05)
    const keys = getKeys() as Record<string, boolean>

    // Yaw. Match mouse-drag's sign: dragging right decrements rotation.y, so ArrowRight does too.
    const turn = (keys.turnLeft ? 1 : 0) - (keys.turnRight ? 1 : 0)
    if (turn) pivot.current.rotation.y += turn * TURN_SPEED * step

    // Pitch. ArrowUp lowers the follow-cam to look up; ArrowDown raises it to look down. Repeat
    // ecctrl's mouse-pitch math on the follow-cam so the camera orbits the same vertical arc.
    const pitch = pitchable ? (keys.lookDown ? 1 : 0) - (keys.lookUp ? 1 : 0) : 0
    if (pitch) {
      const cam = pivot.current.children[0]
      const vy = Math.min(Math.max(cam.rotation.x + pitch * LOOK_SPEED * step, CAM_LOW), CAM_UP)
      const dist = cam.position.length()
      cam.rotation.x = vy
      cam.position.y = -dist * Math.sin(-vy)
      cam.position.z = -dist * Math.cos(-vy)
    }
  })
  return null
}

// How fast the avatar must move over the ground before its body turns to face that way (m/s),
// and how quickly it turns (per second, eased).
const TURNS_AT = 0.3
const BODY_TURN = 10
// In first person, below this ground speed (m/s), an avatar that backs up or steps aside keeps
// facing where it looks and its legs carry it the other way (`PlayerMotion.course`). Faster than
// a walk nobody does, and the body turns to run the way it goes.
const STEPS_BELOW = 2.6

const wrap = (a: number) => Math.atan2(Math.sin(a), Math.cos(a))

/** Measure the avatar after every physics step, so a body posed later in the same frame strides
 *  with this frame's distance. The heading turns toward the direction of travel and holds when
 *  the avatar stops; `faceCamera` (first person) turns it to the camera at rest, and keeps it
 *  there while the avatar backs up or steps aside at a walk. A held body (`pin`) faces the way
 *  the hold says and reads as standing still, however its hold moves it. */
function MotionProbe({
  body,
  motion,
  faceCamera,
  held,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  motion: { current: PlayerMotion }
  faceCamera: boolean
  held: RefObject<PlayerPin | null>
}) {
  const scene = useThree((s) => s.scene)
  const pivot = useRef<Object3D | null>(null)
  useAfterPhysicsStep((world) => {
    const rb = body.current?.group
    if (!rb) return
    const m = motion.current
    const pin = held.current
    const dt = world.timestep
    const v = rb.linvel()
    m.speed = pin ? 0 : Math.hypot(v.x, v.z)
    m.distance += m.speed * dt
    m.vertical = pin ? 0 : v.y
    // ecctrl's ground test, from its float ray.
    m.grounded = pin ? true : (rb.userData as { canJump?: boolean } | undefined)?.canJump === true
    m.pose = pin?.pose ?? null
    m.climb = pin?.climb ?? null
    pivot.current ??= findPivot(scene)
    const camera = pivot.current
    const cameraYaw = camera?.rotation.y ?? m.heading
    const ease = 1 - Math.exp(-BODY_TURN * dt)
    const going = Math.atan2(v.x, v.z)
    // A swimmer always turns to face the way it goes.
    const stepping = faceCamera && !pin && !m.swim && m.speed > TURNS_AT && m.speed < STEPS_BELOW
    if (pin) m.heading += wrap(pin.yaw - m.heading) * ease
    else if (stepping) m.heading += wrap(cameraYaw - m.heading) * ease
    else if (m.speed > TURNS_AT) m.heading += wrap(going - m.heading) * ease
    else if (faceCamera) m.heading += wrap(cameraYaw - m.heading) * ease
    m.heading = wrap(m.heading)
    m.course = stepping ? wrap(going - m.heading) : 0
    m.lookYaw = wrap(cameraYaw - m.heading)
    m.lookPitch = -(camera?.children[0]?.rotation.x ?? 0)
  })
  return null
}

/** Turn the body the avatar carries to its heading. ecctrl squares the whole model to the camera
 *  pivot every frame, so this takes the pivot's yaw back out beneath it. Mounted after
 *  `CameraKeyLook`, so it sees the pivot after this frame's keyboard turn. */
function BodyFacing({
  turn,
  motion,
}: {
  turn: RefObject<Group | null>
  motion: { current: PlayerMotion }
}) {
  const scene = useThree((s) => s.scene)
  const pivot = useRef<Object3D | null>(null)
  useFrame(() => {
    pivot.current ??= findPivot(scene)
    const group = turn.current
    if (!group || !pivot.current) return
    group.rotation.y = motion.current.heading - pivot.current.rotation.y
  })
  return null
}

/** Lower the body the avatar carries onto the ground. ecctrl holds the capsule `FLOAT_HEIGHT`
 *  above it on a spring, applied as one impulse a frame against a frame's worth of gravity, so
 *  the capsule settles lower by m·g·dt / k. Dropping the body by the rest stands its feet (the
 *  capsule's bottom) on the ground at any frame rate. How far it has settled is published as the
 *  motion's `sag`, in first person too, for whoever needs the height of the feet. */
function StandOnGround({
  body,
  lift,
  motion,
  held,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  lift: RefObject<Group | null>
  motion: { current: PlayerMotion }
  held: RefObject<PlayerPin | null>
}) {
  const { gravity } = useWorld()
  useFrame((_, dt) => {
    const rb = body.current?.group
    const group = lift.current
    if (!rb || !group) return
    const g = Math.abs(gravity[1]) * rb.gravityScale()
    const sag = (rb.mass() * g * Math.min(dt, 0.5)) / SPRING_K
    // A held body has no spring under it: its capsule is put the whole float height up.
    const drop = held.current ? FLOAT_HEIGHT : Math.max(FLOAT_HEIGHT - sag, 0)
    // Eased, so frame-time jitter doesn't shake the body.
    group.position.y += (-drop - group.position.y) * Math.min(1, dt * 8)
    motion.current.sag = FLOAT_HEIGHT + group.position.y
  })
  return null
}

/** Hold the avatar to the speed `limitSpeed` allows while something slows it. ecctrl pushes
 *  toward its own pace every frame, so the cap goes on what comes out: the speed over the ground
 *  is scaled back to the limit, and the fall is left alone. */
function SpeedLimit({
  body,
  limit,
  held,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  limit: RefObject<number | null>
  held: RefObject<PlayerPin | null>
}) {
  useFrame(() => {
    const most = limit.current
    const rb = body.current?.group
    if (most === null || !rb || held.current) return
    const v = rb.linvel()
    const speed = Math.hypot(v.x, v.z)
    if (speed <= most) return
    const k = most / speed
    rb.setLinvel({ x: v.x * k, y: v.y, z: v.z * k }, true)
  })
  return null
}

// How far under the surface the bed is looked for, in body heights: past it the water is deep,
// whatever lies below.
const BED_REACH = 1.5
const DOWN = { x: 0, y: -1, z: 0 }

/**
 * Water the avatar gets into (an `Ocean`, a `Lake`, a `Pool`): it slows a walk from the knee up,
 * and where it is over half the body the avatar swims, held at the surface and riding the swell.
 * Leaving the ground over deep water is a dive, the `dive` control swims down under the surface,
 * and swimming into a bank, a step or a low ledge climbs out onto it. Runs before every physics
 * step, after ecctrl has pushed the body, so it has the last word on the step's velocity; what
 * the body is doing goes out on its motion (`swim`, `immersion`, `submerged`). See
 * `player/swim.ts`.
 */
function Swim({
  body,
  motion,
  held,
  shape,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  motion: { current: PlayerMotion }
  held: RefObject<PlayerPin | null>
  shape: SwimShape
}) {
  const { waters } = useWorld()
  const { world, rapier } = useRapier()
  const scene = useThree((three) => three.scene)
  const [, getKeys] = useKeyboardControls()
  const [s] = useState(() => ({
    state: createSwimState(),
    capsule: { y: 0, vx: 0, vy: 0, vz: 0 },
    sense: {
      dt: 0,
      level: null as number | null,
      swell: 0,
      bed: Number.NEGATIVE_INFINITY,
      ahead: Number.NEGATIVE_INFINITY,
      grounded: false,
      pushing: false,
      sprinting: false,
      diving: false,
    },
    sample: { level: 0, swell: 0 },
    ray: new rapier.Ray({ x: 0, y: 0, z: 0 }, DOWN),
    pivot: null as Object3D | null,
  }))
  /** How far down `from` the ground is, within `reach`; null when there is none, or `from` is
   *  inside something solid. */
  const groundUnder = (
    rb: NonNullable<CustomEcctrlRigidBody['group']>,
    from: Vec3,
    reach: number,
  ) => {
    s.ray.origin = { x: from[0], y: from[1], z: from[2] }
    const flags = rapier.QueryFilterFlags.EXCLUDE_SENSORS
    const hit = world.castRay(s.ray, reach, true, flags, undefined, undefined, rb)
    return hit && hit.timeOfImpact > 1e-3 ? hit.timeOfImpact : null
  }

  useBeforePhysicsStep(() => {
    const rb = body.current?.group
    const m = motion.current
    const { state, capsule, sense } = s
    if (!rb || held.current || !rb.isDynamic() || !waters?.size) {
      state.phase = null
      state.line = null
      state.climbing = false
      state.climb = null
      m.swim = null
      m.immersion = 0
      m.submerged = 0
      return
    }
    const at = rb.translation()
    const v = rb.linvel()
    const water = waterAt(waters, at.x, at.y + shape.top, at.z, s.sample)
    const grounded = (rb.userData as { canJump?: boolean } | undefined)?.canJump === true
    sense.dt = world.timestep
    sense.level = water?.level ?? null
    sense.swell = water?.swell ?? 0
    sense.grounded = grounded
    sense.bed = Number.NEGATIVE_INFINITY
    sense.ahead = Number.NEGATIVE_INFINITY
    // Which way the avatar is pushed, as ecctrl reads it: the keys or the stick, from the
    // camera's side.
    const keys = getKeys() as Record<string, boolean>
    const stick = useJoystickControls.getState()
    const across = (keys.leftward ? 1 : 0) - (keys.rightward ? 1 : 0)
    const along = (keys.forward ? 1 : 0) - (keys.backward ? 1 : 0)
    const push =
      stick.curJoystickDis > 0
        ? stick.curJoystickAng - Math.PI / 2
        : across || along
          ? Math.atan2(across, along)
          : null
    sense.pushing = push !== null
    sense.sprinting = keys.run || stick.curRunState
    sense.diving = keys.dive === true
    // The bed matters to a body in the water or in the air over it, not to one standing dry.
    const dry =
      grounded && state.phase === null && water !== null && at.y - shape.feet > water.level
    if (water && !dry) {
      const floor = water.level - BED_REACH * shape.height
      // A body swimming down looks for the bed from where it is.
      const reach = Math.max(at.y - floor, shape.height)
      const under = groundUnder(rb, [at.x, at.y, at.z], reach)
      if (under !== null) sense.bed = at.y - under
      // What a swimmer is pushed into, a little past the capsule: a ledge within reach over the
      // water is climbed onto.
      if (push !== null && state.phase !== 'dive' && state.phase !== 'glide') {
        if (!s.pivot?.parent) s.pivot = findPivot(scene)
        const yaw = (s.pivot?.rotation.y ?? m.heading) + push
        const out = shape.radius + 0.1 * shape.unit
        const top = water.level + water.swell + CLIMB_REACH * shape.unit
        const from: Vec3 = [at.x + Math.sin(yaw) * out, top, at.z + Math.cos(yaw) * out]
        const ledge = groundUnder(rb, from, top - floor)
        if (ledge !== null) sense.ahead = top - ledge
      }
    }

    capsule.y = at.y
    capsule.vx = v.x
    capsule.vy = v.y
    capsule.vz = v.z
    const carried = stepSwim(state, shape, capsule, sense)
    if (capsule.vx !== v.x || capsule.vy !== v.y || capsule.vz !== v.z) {
      rb.setLinvel({ x: capsule.vx, y: capsule.vy, z: capsule.vz }, true)
    }
    // ecctrl sets the gravity it wants every frame; this is the last word before the step.
    if (carried) rb.setGravityScale(0, true)
    m.swim = swimming(state)
    m.immersion = state.immersion
    m.submerged = submersion(state)
  })
  return null
}

/**
 * What the avatar leaves on the water it is in: rings behind it as it swims or wades, and a
 * splash where it goes in (see `water/trail.tsx`). The avatar's own, whatever body it carries and
 * in every view, so there is something to see in first person too. Nothing is mounted until the
 * avatar is first in water, and a held body (on a seat in a hull, say) leaves none.
 */
function Wake({
  body,
  held,
  shape,
  seed,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  held: RefObject<PlayerPin | null>
  shape: SwimShape
  seed: number
}) {
  const { waters } = useWorld()
  const [wet, setWet] = useState(false)
  const [s] = useState(() => ({
    source: { current: { wet: false, x: 0, y: 0, z: 0, fall: 0 } as WakeBody },
    sample: { level: 0, swell: 0 } as WaterSample,
  }))
  useFrame(() => {
    const rb = body.current?.group
    const mark = s.source.current
    mark.wet = false
    if (!rb || held.current || !waters?.size) return
    const at = rb.translation()
    const water = waterAt(waters, at.x, at.y + shape.top, at.z, s.sample)
    if (!water) return
    const surface = water.level + water.swell
    // Feet in the water and the head not far under it: a body wholly under leaves no mark.
    const inWater = at.y - shape.feet < water.level - 0.05 * shape.height
    mark.wet = inWater && at.y + shape.top > surface - 0.15 * shape.unit
    mark.x = at.x
    mark.y = surface
    mark.z = at.z
    mark.fall = Math.max(-rb.linvel().y, 0)
    if (mark.wet && !wet) setWet(true)
  })
  return wet ? <WaterTrail source={s.source} seed={seed} /> : null
}

// How fast a held body is carried to its spot: at least this many meters a second, and most of
// what is left of the way each frame, so a long reach still arrives promptly.
const CARRY_SPEED = 6
const CARRY_RATE = 14

/** Carry a held body to the spot it is held at (see `PlayerControl.pin`). The body is kinematic
 *  while held, so nothing pushes it off and it passes through what it sits on. */
function PinDriver({
  body,
  held,
  centre,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  held: RefObject<PlayerPin | null>
  /** The capsule's centre above the feet, in world units. */
  centre: number
}) {
  const { unit } = useWorld()
  useFrame((_, dt) => {
    const pin = held.current
    const rb = body.current?.group
    if (!pin || !rb) return
    const at = rb.translation()
    const dx = pin.feet[0] - at.x
    const dy = pin.feet[1] + centre - at.y
    const dz = pin.feet[2] - at.z
    const gap = Math.hypot(dx, dy, dz)
    const step = Math.min(dt, 0.1)
    const reach = Math.max(CARRY_SPEED * unit * step, gap * (1 - Math.exp(-CARRY_RATE * step)))
    const k = gap < 1e-4 ? 1 : Math.min(1, reach / gap)
    // Ignored until the body has turned kinematic, a commit after the hold began.
    rb.setNextKinematicTranslation({ x: at.x + dx * k, y: at.y + dy * k, z: at.z + dz * k })
  })
  return null
}

// Rapier gives every collider 16 groups it belongs to and 16 it meets. The camera's casts are made
// in the last group alone, so a collider that leaves that group out of the ones it meets is one
// the camera goes straight through, while every body still runs into it.
const CAMERA_GROUP = 1 << 15
/** `collisionGroups` for a collider the third-person camera may pass through (glass, a stool, a
 *  bead curtain) while bodies still run into it. */
export const CAMERA_PASSES = ((0xffff << 16) | (0xffff & ~CAMERA_GROUP)) >>> 0
const CAMERA_CASTS = ((CAMERA_GROUP << 16) | 0xffff) >>> 0

// The camera goes back out to its distance at this rate (1/s). It comes in at once.
const BOOM_EASE = 5
// The body the avatar carries is not drawn while the camera is this close to its head, and is
// drawn again once the camera is a little further out, so it does not flicker at the edge.
const HIDE_WITHIN = 0.5
const SHOW_BEYOND = 0.65
// A post this thin both ways across (a lamp pole, a railing) does not stop the camera: going
// round one would make the view jump every time the avatar walked past it.
const SLIM = 0.25
// How fast the camera rises over an avatar that starts to swim, and comes back down (1/s).
const TILT_EASE = 2.5
const UPRIGHT = { x: 0, y: 0, z: 0, w: 1 }

/**
 * Holds the camera in the third-person and overhead views: out at the distance and angle
 * ecctrl's rig asks for, or as far that way as it can go before something solid.
 *
 * ecctrl keeps its own camera out of walls with a ray cast at the meshes it found when it
 * mounted. Static batching draws walls, floors and roofs as merged meshes that arrive later, and
 * moves the ones ecctrl found to a layer its ray does not test, so that camera went through them
 * and looked into the next room; overhead, it flew over roofs and showed the roof instead of the
 * avatar. This one asks the physics world, where a wall has a collider however it is drawn: a
 * ball that holds the camera's near plane is swept from the avatar's head toward where the
 * camera wants to be, and the camera stops where the ball does. ecctrl's rig still takes the
 * mouse, the wheel and the look keys.
 *
 * Behind an avatar afloat at the surface the camera rides higher and looks down at it (see
 * `raiseBoom`): level with a swimmer's head it would skim the water and go under with the swell.
 * It is the line out from the avatar that is tilted, not where the sweep starts, so the sweep
 * still begins inside the capsule and stops under a deck as it does under a ceiling.
 */
function CameraBoom({
  body,
  model,
  motion,
  follow,
  lerp,
  pivotUp,
  halfHeight,
  radius,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  /** The group that holds the visible body. */
  model: RefObject<Group | null>
  motion: { current: PlayerMotion }
  /** How fast ecctrl's pivot follows the avatar, and the camera follows a turn of the rig (1/s). */
  follow: number
  lerp: number
  /** Where ecctrl aims its pivot, above the capsule's centre. */
  pivotUp: number
  halfHeight: number
  radius: number
}) {
  const scene = useThree((s) => s.scene)
  const camera = useThree((s) => s.camera)
  const { world, rapier } = useRapier()
  const { unit } = useWorld()
  const rig = useRef<Object3D | null>(null)
  const reach = useRef<number | null>(null)
  const afloat = useRef(0)
  const [v] = useState(() => ({
    aim: new Vector3(),
    from: new Vector3(),
    way: new Vector3(),
    want: new Vector3(),
    dir: new Vector3(),
    ball: new rapier.Ball(0.2),
    slim: new WeakMap<RapierCollider, boolean>(),
  }))

  useFrame((_, delta) => {
    const rb = body.current?.group
    if (!rig.current?.parent) rig.current = findPivot(scene)
    const pivot = rig.current
    if (!rb || !pivot) return

    // ecctrl moves its pivot after this runs (a parent's frame callback comes after its
    // children's). Where it is about to put it is worked out here the way ecctrl does, so the
    // camera is not a frame behind the avatar.
    const dt = delta > 1 ? delta % 1 : delta
    const c = rb.translation()
    v.aim
      .set(c.x, c.y + pivotUp, c.z)
      .sub(pivot.position)
      .multiplyScalar(1 - Math.exp(-follow * dt))
      .add(pivot.position)

    // Where the rig wants the camera: its follow-cam, out behind the pivot and turned with it.
    v.want.copy(pivot.children[0].position).applyQuaternion(pivot.quaternion)
    const far = v.want.length()
    if (far < 1e-4) return
    v.want.divideScalar(far)
    const step = Math.min(dt, 0.1)
    const { swim } = motion.current
    const surfaced = swim === 'swim' || swim === 'climb' ? 1 : 0
    afloat.current += (surfaced - afloat.current) * (1 - Math.exp(-TILT_EASE * step))
    raiseBoom(v.want, SWIM_TILT, afloat.current)
    if (reach.current === null) v.dir.copy(v.want)
    else if (v.dir.lerp(v.want, 1 - Math.exp(-lerp * step)).lengthSq() < 1e-6) v.dir.copy(v.want)
    else v.dir.normalize()

    // A ball round the camera that takes in the corners of its near plane, so nothing the ball
    // clears is cut open by that plane. Kept smaller than the capsule, so it fits wherever the
    // avatar does.
    const lens = camera as PerspectiveCamera
    const tan = lens.isPerspectiveCamera ? Math.tan((lens.fov * Math.PI) / 360) : 0
    const aspect = lens.isPerspectiveCamera ? lens.aspect : 1
    const corner = camera.near * Math.hypot(1, tan, tan * aspect)
    v.ball.radius = Math.min(corner + 0.02 * unit, radius - 0.02 * unit)

    const stops = (collider: RapierCollider) => {
      let slim = v.slim.get(collider)
      if (slim === undefined) {
        slim = false
        if (collider.shapeType() === rapier.ShapeType.Cuboid) {
          const h = collider.halfExtents()
          slim = [h.x, h.y, h.z].sort((a, b) => a - b)[1] <= (SLIM / 2) * unit
        }
        v.slim.set(collider, slim)
      }
      return !slim
    }
    const sweep = (from: Vector3, along: Vector3, most: number) => {
      const hit = world.castShape(
        from,
        UPRIGHT,
        along,
        v.ball,
        0,
        most,
        true,
        rapier.QueryFilterFlags.EXCLUDE_SENSORS,
        CAMERA_CASTS,
        undefined,
        rb,
        stops,
      )
      return hit ? Math.min(most, Math.max(0, hit.time_of_impact)) : most
    }

    // Start inside the capsule, where nothing else can be, and go to the pivot first: it trails
    // the avatar, and on a fast turn round a corner it can cut through the corner.
    v.from.set(c.x, c.y + halfHeight, c.z)
    v.way.copy(v.aim).sub(v.from)
    const gap = v.way.length()
    if (gap > 1e-4) v.from.addScaledVector(v.way.divideScalar(gap), sweep(v.from, v.way, gap))
    const room = sweep(v.from, v.dir, far)
    const was = reach.current ?? room
    const now = room < was ? room : was + (room - was) * (1 - Math.exp(-BOOM_EASE * step))
    reach.current = now
    camera.position.copy(v.from).addScaledVector(v.dir, now)
    camera.lookAt(v.way.copy(camera.position).sub(v.dir))

    // Up against the avatar's head the camera would look out through it.
    const drawn = model.current
    if (drawn?.visible && now < HIDE_WITHIN * unit) drawn.visible = false
    else if (drawn && !drawn.visible && now > SHOW_BEYOND * unit) drawn.visible = true
  })
  return null
}

// How long the avatar waits for ground to appear beneath it before it falls anyway (spawning
// over open water, say), in seconds.
const GROUND_WAIT = 0.5

/** Hold the avatar kinematic until a ray straight down hits a collider, so it can't drop
 *  through ground whose collider arrives a commit or two after the avatar's body. */
function GroundGuard({
  body,
  onGrounded,
}: {
  body: RefObject<CustomEcctrlRigidBody | null>
  onGrounded: () => void
}) {
  const { world, rapier } = useRapier()
  const waited = useRef(0)
  const done = useRef(false)

  useFrame((_, dt) => {
    const rb = body.current?.group
    if (done.current || !rb) return
    waited.current += dt
    const at = rb.translation()
    const ray = new rapier.Ray(at, { x: 0, y: -1, z: 0 })
    const hit = world.castRay(ray, 1000, true, undefined, undefined, undefined, rb)
    if (hit || waited.current > GROUND_WAIT) {
      done.current = true
      onGrounded()
    }
  })
  return null
}

export interface PlayerProps {
  position?: Vec3
  /** Sets how the avatar's splashes scatter. */
  seed?: number
  /** Camera view: `first` (through the avatar's eyes), `third` (behind it), or `overhead` (high
   *  above at a fixed tilt, following it; scroll zooms, WASD walks relative to the screen). Unset
   *  defers to the world default (`<World avatar>`); falls back to first-person. An explicit value
   *  here always wins. A world `view` control (e.g. `controls: { view: ['KeyV'] }`) cycles the
   *  three at runtime. */
  view?: PlayerView
  /** Initial camera yaw in radians (0 faces +z). */
  yaw?: number
  /** How tall the avatar is, feet to crown, in meters: the length of its capsule. */
  height?: number
  /** The capsule's radius, in meters. */
  radius?: number
  /** Eye height above the feet, in meters: where the first-person camera sits, what the
   *  third-person camera turns about, and what others look at when they look at the player.
   *  Unset, just under the top of the capsule as it floats (about 1.4 at the default size). */
  eyeHeight?: number
  /** Top walking speed, in meters per second. */
  speed?: number
  /** Top speed while the `run` key is held, in meters per second. */
  sprintSpeed?: number
  /** Swim in open water (an `Ocean`, a `Lake`, a `Pool`). Water slows a walk from the knee up;
   *  where it is over half the avatar's height the avatar floats at the surface and swims,
   *  leaving the ground over deep water is a dive, and holding the world's `dive` control (C)
   *  swims down under the surface. False leaves water as something to look at: the avatar walks
   *  the bed under it. */
  swim?: boolean
  /** Top swimming speed, in meters per second. Never faster than `speed`. */
  swimSpeed?: number
  /** Top swimming speed while the `run` key is held, in meters per second: a front crawl on a
   *  `Person` body. Never faster than `sprintSpeed`. */
  swimSprintSpeed?: number
  /** The view from under water: while the camera is below the surface of an `Ocean`, a `Lake`
   *  or a `Pool`, the world is fogged with the water's color, as far as the water is clear.
   *  False leaves the view as it is above. */
  underwater?: boolean
  /** How far behind the avatar the third-person camera starts, in meters; scrolling zooms from
   *  there. */
  cameraDistance?: number
  /** How wide the first-person view is, in degrees across, on a 16:9 screen. The default,
   *  140, takes in most of what both eyes see, so the world wraps around you instead of
   *  sitting behind a window. Like most games it follows the screen's shape, not its size: a
   *  wider screen (an ultrawide or curved monitor) keeps the same angle top to bottom and sees
   *  more across, up to 200°; a narrower one sees less across, down to 110°, then holds that
   *  and opens up top to bottom, until a tall phone screen just shows less across. It is drawn
   *  through a gently curved (Panini) lens: true to life straight ahead, the sides squeezed in
   *  rather than stretched as a flat camera would. Third-person and overhead keep the world
   *  camera's own lens. */
  fov?: number
  /** How blurred the very edge of the first-person view is, in CSS pixels, easing to sharp
   *  toward the centre the way peripheral vision does; turn to look at something and it comes
   *  into focus. 0 turns it off. */
  peripheralBlur?: number
  /** Custom avatar visual, replacing the default capsule. Size it to the capsule envelope
   *  (`height` tall, centered at the character origin, so feet go at y = -height / 2: -0.65 at
   *  the default size); the Player lowers it onto the ground beneath the floating capsule and
   *  turns it to face the way it travels (in first person, the camera's way when it stops). It is
   *  hidden in first-person view. A `Person` here walks in step with the avatar, swims and dives
   *  with it, and looks where the camera looks. In world JSON, nest it as a child node of the
   *  Player. */
  children?: ReactNode
}

/** How ecctrl frames each view. `pitch` tilts the camera down (radians); a `locked` pitch can't
 *  be changed by dragging or the look keys. Outside first person the camera itself is held by
 *  `CameraBoom`, which stops it at walls, floors and roofs in both views. */
const CAMERA: Record<
  PlayerView,
  {
    distance: number
    zoom: [number, number]
    pitch: number
    locked: boolean
    turnVel: number
    turnSpeed: number
    follow: number
    lerp: number
  }
> = {
  first: {
    distance: -0.01,
    zoom: [-0.01, -0.01],
    pitch: 0,
    locked: false,
    turnVel: 1,
    turnSpeed: 100,
    follow: 1000,
    lerp: 1000,
  },
  third: {
    distance: -5,
    zoom: [-1.5, -8],
    pitch: 0,
    locked: false,
    turnVel: 0.2,
    turnSpeed: 15,
    follow: 11,
    lerp: 25,
  },
  overhead: {
    distance: -14,
    zoom: [-6, -30],
    pitch: 1,
    locked: true,
    turnVel: 0.2,
    turnSpeed: 15,
    follow: 8,
    lerp: 20,
  },
}
const VIEWS: PlayerView[] = ['first', 'third', 'overhead']

// ecctrl's float spring, passed explicitly because `StandOnGround` depends on both.
const FLOAT_HEIGHT = 0.3
const SPRING_K = 1.2

/** How far below `FLOAT_HEIGHT` the capsule rides at 60 fps: the spring's sag under the capsule's
 *  own weight (rapier gives a collider a density of 1), as `StandOnGround` works it out. */
function restingSag(radius: number, halfHeight: number, gravity: number) {
  const mass = Math.PI * radius * radius * (2 * halfHeight + (4 / 3) * radius)
  return (mass * gravity) / 60 / SPRING_K
}

/** Move the avatar's body, and its camera with it so the view doesn't sweep across the world.
 *  False when the body doesn't exist yet. */
function moveAvatar(
  ecctrl: CustomEcctrlRigidBody | null,
  scene: Scene,
  camera: Camera,
  to: Vec3,
  { yaw, keepVelocity = false }: TeleportOptions,
) {
  const rb = ecctrl?.group
  if (!rb) return false
  const from = rb.translation()
  const offset = new Vector3(to[0] - from.x, to[1] - from.y, to[2] - from.z)
  rb.setTranslation({ x: to[0], y: to[1], z: to[2] }, true)
  if (!keepVelocity) rb.setLinvel({ x: 0, y: 0, z: 0 }, true)

  const pivot = findPivot(scene)
  if (!pivot) return true
  pivot.position.add(offset)
  // The camera turns with the pivot; the body takes the same heading from `Player`'s motion.
  if (yaw !== undefined) pivot.rotation.y = yaw
  // Put the camera where the follow-cam wants it, so neither the jump nor a new heading is lerped.
  pivot.updateMatrixWorld(true)
  pivot.children[0].getWorldPosition(camera.position)
  camera.lookAt(pivot.position)
  return true
}

export function Player({
  position = [0, 3, 0],
  seed = 1,
  view,
  yaw = 0,
  height = 1.3,
  radius = 0.3,
  eyeHeight,
  speed = 2.5,
  sprintSpeed = 5,
  swim = true,
  swimSpeed = 1.5,
  swimSprintSpeed = 2.6,
  underwater = true,
  cameraDistance = 5,
  fov = 140,
  peripheralBlur = 4,
  children,
}: PlayerProps) {
  const { avatar, player, playerControl, playerMotion, keyboard, controls, gravity, unit } =
    useWorld()
  const scene = useThree((s) => s.scene)
  const camera = useThree((s) => s.camera)
  const wanted = view ?? avatar ?? 'first'
  const [current, setCurrent] = useState<PlayerView>(wanted)
  useEffect(() => setCurrent(wanted), [wanted])
  const firstPerson = current === 'first'
  const cam = useMemo(() => {
    if (current !== 'third') return CAMERA[current]
    const far = Math.max(cameraDistance, 0.5)
    return {
      ...CAMERA.third,
      distance: -far,
      zoom: [Math.max(CAMERA.third.zoom[0], -far), Math.min(CAMERA.third.zoom[1], -far)],
    } satisfies (typeof CAMERA)[PlayerView]
  }, [current, cameraDistance])
  const eyes = useRef<Object3D>(null)
  const body = useRef<CustomEcctrlRigidBody>(null)
  const [grounded, setGrounded] = useState(false)
  const motion = useRef<PlayerMotion>({
    speed: 0,
    distance: 0,
    vertical: 0,
    grounded: false,
    heading: yaw,
    lookYaw: 0,
    lookPitch: 0,
  })
  const lift = useRef<Group>(null)
  const turn = useRef<Group>(null)
  const capsule = useMaterial({ color: '#4a90d9' })
  // Something in the world holds the body in place (see `PlayerControl.pin`): where, whether the
  // body has turned kinematic for it yet, and where to put it when it is let go.
  const pin = useRef<PlayerPin | null>(null)
  const [pinned, setPinned] = useState(false)
  const holding = useRef(false)
  const exit = useRef<Vec3 | null>(null)
  const speedLimit = useRef<number | null>(null)

  const capsuleRadius = Math.min(Math.max(radius, 0.05), height / 2)
  const halfHeight = Math.max(height / 2 - capsuleRadius, 0.01)
  // ecctrl's camera turns about a point `halfHeight + radius / 2` above the capsule's centre, plus
  // `camTargetPos`. An `eyeHeight` is from the feet, which stand `FLOAT_HEIGHT` (less the spring's
  // sag) below the capsule's bottom.
  const centre = FLOAT_HEIGHT - restingSag(capsuleRadius, halfHeight, Math.abs(gravity[1]))
  const eyeOffset =
    eyeHeight === undefined
      ? halfHeight + capsuleRadius / 2
      : eyeHeight - centre - halfHeight - capsuleRadius
  const camTarget = useMemo(
    () => ({ x: 0, y: eyeOffset - halfHeight - capsuleRadius / 2, z: 0 }),
    [eyeOffset, halfHeight, capsuleRadius],
  )
  const swimShape = useMemo<SwimShape>(
    () => ({
      feet: halfHeight + capsuleRadius + FLOAT_HEIGHT,
      top: halfHeight + capsuleRadius,
      radius: capsuleRadius,
      height: (halfHeight + capsuleRadius) * 2,
      unit,
      walk: speed,
      sprint: sprintSpeed,
      swim: swimSpeed,
      swimSprint: swimSprintSpeed,
    }),
    [halfHeight, capsuleRadius, unit, speed, sprintSpeed, swimSpeed, swimSprintSpeed],
  )

  // ecctrl reads its camera and capsule setup once, at mount, so a new view or size remounts it:
  // from where the avatar stands now, facing the way the camera faced. The old camera pivot is
  // taken out of the scene so nothing finds it again.
  const setup = `${current}:${halfHeight}:${capsuleRadius}:${cam.distance}`
  const [mount, setMount] = useState({ setup, at: position, yaw })
  useLayoutEffect(() => {
    if (mount.setup === setup) return
    const pivot = findPivot(scene)
    const t = body.current?.group?.translation()
    pivot?.removeFromParent()
    setMount({
      setup,
      at: t ? [t.x, t.y, t.z] : mount.at,
      yaw: pivot?.rotation.y ?? mount.yaw,
    })
  }, [setup, scene, mount])

  useEffect(() => {
    const keys = controls.view
    if (!keyboard || !keys?.length) return
    // One step per press: the page's key repeat arrives as more keydowns.
    const held = new Set<string>()
    const onDown = (event: Event) => {
      const { code } = event as KeyboardEvent
      if (!keys.includes(code) || held.has(code)) return
      held.add(code)
      setCurrent((v) => VIEWS[(VIEWS.indexOf(v) + 1) % VIEWS.length])
    }
    const onUp = (event: Event) => held.delete((event as KeyboardEvent).code)
    keyboard.addEventListener('keydown', onDown)
    keyboard.addEventListener('keyup', onUp)
    return () => {
      keyboard.removeEventListener('keydown', onDown)
      keyboard.removeEventListener('keyup', onUp)
    }
  }, [keyboard, controls])

  // Publish the avatar so the world can react to the player rather than the camera. Only clear
  // the slot if it's still ours, so a remount elsewhere isn't wiped by this unmount.
  useEffect(() => {
    if (!player) return
    const anchor = eyes.current
    player.current = anchor
    return () => {
      if (player.current === anchor) player.current = null
    }
    // A new view or size remounts ecctrl, and with it the anchor.
  }, [player, mount.setup])

  useEffect(() => {
    if (!playerMotion) return
    const mine = motion.current
    playerMotion.current = mine
    return () => {
      if (playerMotion.current === mine) playerMotion.current = null
    }
  }, [playerMotion])

  // A teleport asked for before the body exists (just mounted, or remounting for a new view)
  // waits for it.
  const pendingTeleport = useRef<[Vec3, TeleportOptions] | null>(null)
  useEffect(() => {
    if (!playerControl) return
    const control: PlayerControl = {
      teleport(to, options = {}) {
        if (options.yaw !== undefined) motion.current.heading = options.yaw
        const moved = moveAvatar(body.current, scene, camera, to, options)
        pendingTeleport.current = moved ? null : [to, options]
      },
      pin(spot, to) {
        pin.current = spot
        if (spot) exit.current = null
        // A body that never turned kinematic can be moved straight away.
        else if (!holding.current) {
          if (to) control.teleport(to)
        } else exit.current = to ?? null
        setPinned(spot !== null)
      },
      limitSpeed(most) {
        speedLimit.current = most
      },
    }
    playerControl.current = control
    return () => {
      if (playerControl.current === control) playerControl.current = null
    }
  }, [playerControl, scene, camera])
  useFrame(() => {
    const queued = pendingTeleport.current
    if (!queued) return
    if (moveAvatar(body.current, scene, camera, ...queued)) {
      pendingTeleport.current = null
    }
  })

  // The body turns kinematic or dynamic a commit after `pin` asks, and turning resets it to where
  // it was drawn last. So a body let go somewhere else is moved there here, after the turn (a
  // child's effects run before its parent's).
  useEffect(() => {
    holding.current = pinned
    if (pinned || !exit.current) return
    playerControl?.current?.teleport(exit.current)
    exit.current = null
  }, [pinned, playerControl])

  return (
    <Ecctrl
      key={mount.setup}
      ref={body}
      type={grounded && !pinned ? 'dynamic' : 'kinematicPosition'}
      disableControl={pinned}
      position={mount.at}
      mode="CameraBasedMovement"
      camInitDir={{ x: cam.pitch, y: mount.yaw }}
      characterInitDir={mount.yaw}
      // A locked capsule can't tip over; ecctrl turns only the visible model to face the way it
      // walks. Its balancing torque, applied once per rendered frame, could topple the avatar
      // when frames came slowly.
      autoBalance={false}
      {...(cam.locked ? { camUpLimit: cam.pitch, camLowLimit: cam.pitch } : {})}
      // Outside first person the camera is `CameraBoom`'s: ecctrl's rig goes on taking the mouse
      // and the wheel, and its own follow camera and wall test stay out of the way.
      disableFollowCam={!firstPerson}
      camCollision={firstPerson}
      capsuleRadius={capsuleRadius}
      capsuleHalfHeight={halfHeight}
      floatHeight={FLOAT_HEIGHT}
      springK={SPRING_K}
      maxVelLimit={speed}
      sprintMult={speed > 0 ? sprintSpeed / speed : 1}
      camTargetPos={camTarget}
      camInitDis={cam.distance}
      camMinDis={cam.zoom[0]}
      camMaxDis={cam.zoom[1]}
      turnVelMultiplier={cam.turnVel}
      turnSpeed={cam.turnSpeed}
      camFollowMult={cam.follow}
      camLerpMult={cam.lerp}
    >
      <Dynamic>
        <group ref={lift} visible={!firstPerson} position={[0, -FLOAT_HEIGHT, 0]}>
          <group ref={turn}>
            <PlayerMotionContext.Provider value={motion}>
              {children ?? (
                <mesh material={capsule} castShadow>
                  <capsuleGeometry args={[capsuleRadius, halfHeight * 2, 8, 16]} />
                </mesh>
              )}
            </PlayerMotionContext.Provider>
          </group>
        </group>
      </Dynamic>
      <object3D ref={eyes} position={[0, eyeOffset, 0]} />
      <CameraKeyLook pitchable={!cam.locked} />
      <BodyFacing turn={turn} motion={motion} />
      {firstPerson && <PaniniLens fov={fov} blur={peripheralBlur} />}
      {!firstPerson && (
        <CameraBoom
          body={body}
          model={lift}
          motion={motion}
          follow={cam.follow}
          lerp={cam.lerp}
          pivotUp={eyeOffset}
          halfHeight={halfHeight}
          radius={capsuleRadius}
        />
      )}
      <MotionProbe body={body} motion={motion} faceCamera={firstPerson} held={pin} />
      <StandOnGround body={body} lift={lift} motion={motion} held={pin} />
      {!grounded && <GroundGuard body={body} onGrounded={() => setGrounded(true)} />}
      <PinDriver body={body} held={pin} centre={halfHeight + capsuleRadius + FLOAT_HEIGHT} />
      {swim && <Swim body={body} motion={motion} held={pin} shape={swimShape} />}
      <Wake body={body} held={pin} shape={swimShape} seed={seed} />
      {/* Not while the avatar is held: a seat low in a hull is under the sea's level, and dry. */}
      {underwater && !pinned && <Underwater />}
      <SpeedLimit body={body} limit={speedLimit} held={pin} />
    </Ecctrl>
  )
}

// Mounted wherever the viewer is when a world streams.
Player.stream = false

import { useFrame, useThree } from '@react-three/fiber'
import { type Lens, lazyModule, useNodeRenderer, useWorld } from '@runek/core'
import { useEffect, useLayoutEffect, useMemo } from 'react'
import {
  HalfFloatType,
  LinearMipmapLinearFilter,
  Matrix4,
  Mesh,
  OrthographicCamera,
  PerspectiveCamera,
  PlaneGeometry,
  Scene,
  ShaderMaterial,
  SRGBColorSpace,
  Vector2,
  Vector3,
  WebGLRenderTarget,
} from 'three'

// A Panini projection: the view is wrapped onto a cylinder around the eye and seen from a point
// `CURVE` radii behind it. Straight ahead it matches a flat camera, verticals stay vertical,
// and the sides squeeze in instead of stretching, so it can show 140° to 200° across without
// the tunnel a flat camera gives. Up to 150° across (a 16:9 screen at the default 140°) the scene
// is drawn once, by a flat camera wide enough to cover it, and warped into the curve in one
// full-screen pass that also blurs the periphery. Wider than that (an ultrawide) a flat render
// would stretch its edges too far, so three cameras draw it, ahead, left and right, each covering
// only the slice of the screen it serves, and the same pass stitches them.

// How far behind the eye the cylinder is seen from: 0 is a flat camera (straight lines, stretched
// sides), 1 squeezes the sides most but bows horizontal lines. Halfway keeps lines gently curved.
const CURVE = 0.5
// How the view fits the screen's shape, as games do: on a 16:9 screen it is exactly `fov` across.
// Wider screens keep the same angle top to bottom and see more across (an ultrawide sees around
// you); narrower ones see less across, down to `NARROWEST` degrees, then hold that and open up top
// to bottom instead, until `MAX_VERTICAL_FOV` makes a tall screen show less across.
const REFERENCE_ASPECT = 16 / 9
const NARROWEST = 110
// The widest the view may open across, with all three cameras still covering it.
const MAX_FOV = 200
// The tallest it may open through the centre, so a tall screen narrows the view instead of
// looking down a well.
const MAX_VERTICAL_FOV = 120
// Where focus starts to fall off and where it is fully blurred, as an ellipse of angles off
// straight ahead (across, then up): wider than tall, like the eye's own field.
const FOCUS = { across: (70 * Math.PI) / 180, up: (45 * Math.PI) / 180, from: 0.5, to: 1.3 }
// Where the side cameras take over from the forward one, either side of straight ahead.
const SEAM = Math.PI / 4
// The widest view (half-angle across) one flat camera draws; past it, three cameras do. Past
// 75° a flat render stretches its edges so far that drawing the scene three times is cheaper.
const SINGLE_MAX = (75 * Math.PI) / 180
// Slack around each camera's slice (in tangent units), so sampling at a seam never runs off it.
const PAD = 0.02

/** How far across the projection plane a direction `phi` radians off straight ahead lands. */
const across = (phi: number) => ((CURVE + 1) * Math.sin(phi)) / (CURVE + Math.cos(phi))

/** The inverse of `across`: the angle off straight ahead seen at `x` across the plane. */
function angle(x: number) {
  const k = x / (CURVE + 1)
  return Math.atan(k) + Math.asin((k * CURVE) / Math.sqrt(1 + k * k))
}

const half = (degrees: number) => (degrees * Math.PI) / 360

/** The lens's half-extent on the projection plane, horizontally and vertically, for a screen
 *  `aspect` wide to its height (see `REFERENCE_ASPECT`). */
function bounds(fov: number, aspect: number): Vector2 {
  let x = (across(half(fov)) / REFERENCE_ASPECT) * aspect
  x = Math.max(x, across(half(Math.min(fov, NARROWEST))))
  x = Math.min(x, across(half(MAX_FOV)))
  const y = Math.min(x / aspect, Math.tan(half(MAX_VERTICAL_FOV)))
  return new Vector2(y * aspect, y)
}

function panini(extent: Vector2): Lens {
  return {
    project(p) {
      const h = Math.hypot(p.x, p.z)
      const phi = Math.atan2(p.x, -p.z)
      if (h < 1e-6 || CURVE + Math.cos(phi) < 0.05) return null
      const s = (CURVE + 1) / (CURVE + Math.cos(phi))
      return p.set((s * Math.sin(phi)) / extent.x, (s * p.y) / h / extent.y, 0)
    },
    unproject(ndc, target) {
      const phi = angle(ndc.x * extent.x)
      const t = (ndc.y * extent.y * (CURVE + Math.cos(phi))) / (CURVE + 1)
      return target.set(Math.sin(phi), t, -Math.cos(phi)).normalize()
    },
  }
}

interface View {
  camera: PerspectiveCamera
  /** Turns the forward camera to face this way, in camera space. */
  turn: Matrix4
  target: WebGLRenderTarget
  /** Camera-space direction → this view's clip space, for the stitching pass. */
  sample: Matrix4
  used: boolean
}

// The WebGPU (TSL) twin of the stitching pass, loaded only under a node renderer.
const lensNodes = lazyModule(() => import('../nodes/lens'))

function makeView(node: boolean): View {
  const target = new WebGLRenderTarget(1, 1, node ? { type: HalfFloatType } : undefined)
  if (!node) {
    // Marked as XR so three tone-maps and encodes each material into it exactly as it would onto
    // the screen (respecting `toneMapped: false`), stored as plain 8-bit sRGB: the stitching pass
    // then copies pixels rather than redoing the color pipeline. Under WebGPU the views hold
    // linear light instead, and the frame's output pass tone-maps the stitched screen once.
    target.texture.colorSpace = SRGBColorSpace
    target.texture.internalFormat = 'RGBA8'
    ;(target as { isXRRenderTarget?: boolean }).isXRRenderTarget = true
  }
  // Mipmapped and anisotropically filtered, so the periphery blur reads a pre-shrunk footprint in
  // a few taps however stretched the view is there.
  target.texture.generateMipmaps = true
  target.texture.minFilter = LinearMipmapLinearFilter
  target.texture.anisotropy = 16
  const camera = new PerspectiveCamera()
  camera.matrixAutoUpdate = false
  camera.matrixWorldAutoUpdate = false
  return {
    camera,
    turn: new Matrix4(),
    target,
    sample: new Matrix4(),
    used: true,
  }
}

const VERTEX = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position.xy, 0.0, 1.0);
}
`

const FRAGMENT = /* glsl */ `
uniform sampler2D uAhead;
uniform sampler2D uLeft;
uniform sampler2D uRight;
uniform mat4 uAheadM;
uniform mat4 uLeftM;
uniform mat4 uRightM;
uniform vec2 uExtent;
uniform vec2 uResolution;
uniform float uBlur;
uniform float uSeam;
varying vec2 vUv;

const float CURVE = ${CURVE.toFixed(4)};

vec2 project(mat4 m, vec3 dir) {
  vec4 c = m * vec4(dir, 1.0);
  return c.xy / c.w * 0.5 + 0.5;
}

// The direction seen at a point on the screen, one unit out from the eye's vertical axis.
vec3 ray(vec2 uv) {
  vec2 p = (uv * 2.0 - 1.0) * uExtent;
  float k = p.x / (CURVE + 1.0);
  float phi = atan(k) + asin(k * CURVE / sqrt(1.0 + k * k));
  return vec3(sin(phi), p.y * (CURVE + cos(phi)) / (CURVE + 1.0), -cos(phi));
}

// One view's pixel for dir, blurred by sigma screen pixels. nextX and nextY (the directions one
// screen pixel across and up) give how this view's texels map onto the screen here, which a flat
// render stretches more across than up toward its edges; the four taps and their filter footprint
// follow that map, so the blur stays round on screen whichever view it reads.
vec4 look(sampler2D view, mat4 m, vec3 dir, vec3 nextX, vec3 nextY, float sigma) {
  vec2 uv = project(m, dir);
  if (sigma < 0.35) return textureLod(view, uv, 0.0);
  vec2 gx = (project(m, nextX) - uv) * sigma;
  vec2 gy = (project(m, nextY) - uv) * sigma;
  return 0.25 * (textureGrad(view, uv + 0.7 * gx + 0.28 * gy, gx, gy)
               + textureGrad(view, uv - 0.28 * gx + 0.7 * gy, gx, gy)
               + textureGrad(view, uv - 0.7 * gx - 0.28 * gy, gx, gy)
               + textureGrad(view, uv + 0.28 * gx - 0.7 * gy, gx, gy));
}

void main() {
  // Focus falls off smoothly with the angle off straight ahead, so a wider screen shows more
  // periphery rather than a wider sharp patch.
  vec3 dir = ray(vUv);
  float phi = atan(dir.x, -dir.z);
  vec2 off = vec2(phi / ${FOCUS.across.toFixed(6)}, atan(dir.y) / ${FOCUS.up.toFixed(6)});
  float sigma = uBlur * smoothstep(${FOCUS.from.toFixed(2)}, ${FOCUS.to.toFixed(2)}, length(off));
  vec3 nx = sigma < 0.35 ? dir : ray(vUv + vec2(1.0 / uResolution.x, 0.0));
  vec3 ny = sigma < 0.35 ? dir : ray(vUv + vec2(0.0, 1.0 / uResolution.y));
  if (phi > uSeam) gl_FragColor = look(uRight, uRightM, dir, nx, ny, sigma);
  else if (phi < -uSeam) gl_FragColor = look(uLeft, uLeftM, dir, nx, ny, sigma);
  else gl_FragColor = look(uAhead, uAheadM, dir, nx, ny, sigma);
}
`

/**
 * Draw the world through a Panini lens `fov` degrees across, in place of the camera's own flat
 * projection, while mounted, blurring toward the edges by up to `blur` CSS pixels. Takes over the
 * frame's render (a `useFrame` at priority 1), maps pointer events through the lens, and
 * publishes it as the world's `lens` so labels follow.
 */
export function PaniniLens({ fov, blur }: { fov: number; blur: number }) {
  const gl = useThree((s) => s.gl)
  const camera = useThree((s) => s.camera)
  const size = useThree((s) => s.size)
  const dpr = useThree((s) => s.viewport.dpr)
  const setEvents = useThree((s) => s.setEvents)
  const getState = useThree((s) => s.get)
  const { lens } = useWorld()

  const extent = useMemo(() => bounds(fov, size.width / size.height), [fov, size])
  const optics = useMemo(() => panini(extent), [extent])

  const nodes = useNodeRenderer() ? lensNodes() : null
  const views = useMemo(() => {
    const node = !!nodes
    return { ahead: makeView(node), left: makeView(node), right: makeView(node) }
  }, [nodes])
  const pass = useMemo(() => {
    const uniforms = {
      uAhead: { value: views.ahead.target.texture },
      uLeft: { value: views.left.target.texture },
      uRight: { value: views.right.target.texture },
      uAheadM: { value: views.ahead.sample },
      uLeftM: { value: views.left.sample },
      uRightM: { value: views.right.sample },
      uExtent: { value: new Vector2() },
      uResolution: { value: new Vector2() },
      uBlur: { value: 0 },
      uSeam: { value: SEAM },
    }
    const material = nodes
      ? nodes.lensPassMaterial(uniforms, CURVE, FOCUS)
      : new ShaderMaterial({
          vertexShader: VERTEX,
          fragmentShader: FRAGMENT,
          uniforms,
          depthTest: false,
          depthWrite: false,
          toneMapped: false,
        })
    const quad = new Mesh(new PlaneGeometry(2, 2), material)
    quad.frustumCulled = false
    const scene = new Scene()
    scene.add(quad)
    return { scene, camera: new OrthographicCamera(), material, quad, uniforms }
  }, [views, nodes])

  useEffect(
    () => () => {
      for (const view of Object.values(views)) view.target.dispose()
      pass.material.dispose()
      pass.quad.geometry.dispose()
    },
    [views, pass],
  )

  // Fit each camera's frustum to the slice of the screen it serves, and size its target so
  // straight ahead keeps the screen's pixel density.
  useLayoutEffect(() => {
    const { near, far } = camera as PerspectiveCamera
    const widest = angle(extent.x)
    // Up to `SINGLE_MAX` the forward camera covers the whole view and the sides rest.
    const single = widest <= SINGLE_MAX
    const ahead = single ? widest : Math.min(widest, SEAM)
    // Each view's vertical reach is greatest along the screen's top edge; walk it.
    const reach = (from: number, to: number, yaw: number) => {
      let up = 0
      for (let i = 0; i <= 64; i++) {
        const phi = from + ((to - from) * i) / 64
        const t = (extent.y * (CURVE + Math.cos(phi))) / (CURVE + 1)
        up = Math.max(up, t / Math.cos(phi - yaw))
      }
      return up
    }
    const sides = !single && widest > SEAM
    // Each side camera faces the middle of its slice, so its frustum is symmetric. Facing away
    // from the slice left a lopsided frustum through which some rasterizers (SwiftShader) drop
    // parts of large triangles, showing what lies under the ground.
    const side = (SEAM + widest) / 2
    const sideHalf = Math.tan((widest - SEAM) / 2)
    const sideUp = sides ? reach(SEAM, widest, side) : 0
    const spans = [
      {
        view: views.ahead,
        used: true,
        yaw: 0,
        half: Math.tan(ahead),
        up: reach(0, ahead, 0),
      },
      { view: views.left, used: sides, yaw: side, half: sideHalf, up: sideUp },
      { view: views.right, used: sides, yaw: -side, half: sideHalf, up: sideUp },
    ]

    const density = (size.width * dpr) / (2 * extent.x)
    // WebGPURenderer keeps no WebGL `capabilities`; 8192 is WebGPU's guaranteed minimum.
    const limit =
      (gl as { capabilities?: { maxTextureSize: number } }).capabilities?.maxTextureSize ?? 8192
    // The views build their own projections: in the renderer's clip space (WebGPU's depth runs
    // 0..1), and marked so, or the renderer would rebuild them from the camera's `fov`.
    const system = gl.coordinateSystem
    const turned = new Matrix4()
    for (const span of spans) {
      const { view } = span
      view.used = span.used
      if (!span.used) continue
      view.turn.makeRotationY(span.yaw)
      const right = span.half + PAD
      const left = -right
      const up = span.up + PAD
      view.target.setSize(
        Math.min(limit, Math.max(1, Math.ceil((right - left) * density))),
        Math.min(limit, Math.max(1, Math.ceil(2 * up * density))),
      )
      view.camera.near = near
      view.camera.far = far
      view.camera.coordinateSystem = system
      view.camera.projectionMatrix.makePerspective(
        left * near,
        right * near,
        up * near,
        -up * near,
        near,
        far,
        system,
      )
      view.camera.projectionMatrixInverse.copy(view.camera.projectionMatrix).invert()
      view.sample.copy(view.camera.projectionMatrix).multiply(turned.copy(view.turn).invert())
    }
    const { uniforms } = pass
    uniforms.uExtent.value.copy(extent)
    uniforms.uResolution.value.set(size.width * dpr, size.height * dpr)
    uniforms.uBlur.value = blur * dpr
    uniforms.uSeam.value = single ? Math.PI : SEAM
  }, [views, pass, extent, size, dpr, camera, gl, blur])

  // Publish the lens, and aim pointer rays through it rather than the flat camera.
  useEffect(() => {
    if (lens) lens.current = optics
    const previous = getState().events.compute
    const dir = new Vector3()
    const eye = new Vector3()
    setEvents({
      compute: (event, state) => {
        state.pointer.set(
          (event.offsetX / state.size.width) * 2 - 1,
          -(event.offsetY / state.size.height) * 2 + 1,
        )
        const { camera, raycaster } = state
        optics.unproject(state.pointer, dir).transformDirection(camera.matrixWorld)
        raycaster.set(camera.getWorldPosition(eye), dir)
        raycaster.camera = camera
      },
    })
    return () => {
      if (lens?.current === optics) lens.current = null
      setEvents({ compute: previous })
    }
  }, [optics, lens, setEvents, getState])

  useFrame(({ scene }) => {
    // The controller has moved the camera this frame; nothing has folded that into its matrix.
    camera.updateMatrixWorld()
    const shadows = gl.shadowMap.autoUpdate
    const transforms = scene.matrixWorldAutoUpdate
    const target = gl.getRenderTarget()
    let first = true
    for (const view of Object.values(views)) {
      if (!view.used) continue
      view.camera.layers.mask = camera.layers.mask
      view.camera.matrixWorld.multiplyMatrices(camera.matrixWorld, view.turn)
      view.camera.matrixWorldInverse.copy(view.camera.matrixWorld).invert()
      gl.setRenderTarget(view.target)
      gl.render(scene, view.camera)
      // Shadows and transforms are the same from every side: settle them once a frame.
      if (first) {
        gl.shadowMap.autoUpdate = false
        scene.matrixWorldAutoUpdate = false
      }
      first = false
    }
    gl.shadowMap.autoUpdate = shadows
    scene.matrixWorldAutoUpdate = transforms
    gl.setRenderTarget(target)
    gl.render(pass.scene, pass.camera)
  }, 1)

  return null
}

import { useFrame, useThree } from '@react-three/fiber'
import { DYNAMIC_KEY, skipMirrors, useWorld, type WaterSample, waterAt } from '@runek/core'
import { useEffect, useState } from 'react'
import { BackSide, Color, Fog, Mesh, MeshBasicMaterial, SphereGeometry } from 'three'

// What water that says nothing of itself looks like from inside (`WaterBody.color`, `clarity`):
// its color, and how far one sees through it, in meters.
const COLOR = '#1f6f8c'
const CLARITY = 20
/** Where the fog starts, as a part of how far one sees: behind the camera, so that whatever is in
 *  the water is tinted by it, however near. */
const NEAR = -0.3
/** The camera is under once it is this far below the surface, in meters. */
const UNDER = 0.03
// A fog that fogs nothing, for a world without one (see below).
const CLEAR = [1e6, 1e7] as const

/** Whether `fog` is a linear one, whose range can be changed in place. */
const isLinear = (fog: unknown): fog is Fog => (fog as Fog | null)?.isFog === true

/**
 * The view from under water. While the camera is below the surface of water in the world (an
 * `Ocean`, a `Lake`, a `Pool`), the world's distance fog becomes the water: its color, and a
 * range as short as the water is clear. A sphere of that color at the end of the range stands
 * in for everything further off, the sky included, which no fog reaches.
 *
 * The fog the world already has is changed in place and put back on the way out, so no material
 * is compiled again under either renderer. A world without fog is given one that fogs nothing
 * the first time there is water in it, for the same reason. Mounted by `Player`; a world with a
 * camera of its own can mount one beside it.
 */
export function Underwater() {
  const scene = useThree((three) => three.scene)
  const { waters, unit } = useWorld()
  const [v] = useState(() => {
    const backdrop = new Mesh(
      new SphereGeometry(1, 24, 12),
      new MeshBasicMaterial({ side: BackSide, fog: false }),
    )
    backdrop.visible = false
    backdrop.frustumCulled = false
    backdrop.userData[DYNAMIC_KEY] = true
    return {
      backdrop,
      own: new Fog('#ffffff', ...CLEAR),
      // The fog being stood in for, and what it was.
      kept: null as { fog: Fog; color: Color; near: number; far: number } | null,
      sample: { level: 0, swell: 0 } as WaterSample,
      color: new Color(),
      named: '',
    }
  })

  useEffect(() => {
    const { backdrop, own } = v
    scene.add(backdrop)
    const mirrored = skipMirrors(backdrop)
    return () => {
      mirrored()
      scene.remove(backdrop)
      surface(v)
      if (scene.fog === own) scene.fog = null
    }
  }, [scene, v])
  useEffect(
    () => () => {
      v.backdrop.geometry.dispose()
      v.backdrop.material.dispose()
    },
    [v],
  )

  useFrame(({ camera }) => {
    if (!waters?.size) return surface(v)
    if (!scene.fog) scene.fog = v.own
    const at = camera.position
    const water = waterAt(waters, at.x, at.y, at.z, v.sample)
    const fog = scene.fog
    if (!water || at.y > water.level + water.swell - UNDER * unit || !isLinear(fog)) {
      return surface(v)
    }
    if (v.kept?.fog !== fog) {
      surface(v)
      v.kept = { fog, color: fog.color.clone(), near: fog.near, far: fog.far }
    }
    const named = water.body?.color ?? COLOR
    if (named !== v.named) {
      v.named = named
      v.color.set(named)
    }
    const clarity = water.body?.clarity ?? CLARITY * unit
    fog.color.copy(v.color)
    fog.near = NEAR * clarity
    fog.far = clarity
    // Just inside where the fog closes, so nothing shows a hard edge against it.
    v.backdrop.visible = true
    v.backdrop.position.copy(at)
    v.backdrop.scale.setScalar(clarity * 0.98)
    v.backdrop.material.color.copy(v.color)
  })
  return null
}

/** Back above the water: put the world's fog back as it was. */
function surface(v: {
  backdrop: Mesh
  kept: { fog: Fog; color: Color; near: number; far: number } | null
}) {
  v.backdrop.visible = false
  if (!v.kept) return
  const { fog, color, near, far } = v.kept
  fog.color.copy(color)
  fog.near = near
  fog.far = far
  v.kept = null
}

// Where the third-person camera rides while its avatar swims.
import type { Vector3 } from 'three'

/** The least the camera stands over an avatar afloat at the surface: the angle of its line from
 *  the avatar above the level, in radians. Level behind a swimmer it would skim the water, a
 *  hand's width over it, and go under with every swell. */
export const SWIM_TILT = 0.36

/**
 * Raise `dir`, the unit direction from the avatar to its camera, toward standing at least `tilt`
 * radians over the level: all the way at a `weight` of 1, not at all at 0. It keeps the way it
 * points across the ground. A line already steeper is left alone, as is one straight up or down.
 * Changes `dir` in place and returns it.
 */
export function raiseBoom(dir: Vector3, tilt: number, weight: number): Vector3 {
  const flat = Math.hypot(dir.x, dir.z)
  if (weight <= 0 || flat < 1e-4) return dir
  const now = Math.atan2(dir.y, flat)
  if (now >= tilt) return dir
  const to = now + (tilt - now) * Math.min(weight, 1)
  const k = Math.cos(to) / flat
  return dir.set(dir.x * k, Math.sin(to), dir.z * k)
}

// What water does to the avatar: when it wades, swims, dives and goes under, and the buoyancy and
// drag that carry it. Plain numbers in and out, so it is tested without a physics world; `Player` feeds it
// the capsule before every physics step.
import type { PlayerSwim } from '@runek/core'

/** Swim when the still water is over this much of the body, feet to crown. */
export const SWIM_AT = 0.5
/** Stand again when the water is shallower than this much of the body. Under `SWIM_AT`, so a
 *  body on a sloping beach doesn't flicker between the two. */
export const STAND_AT = 0.45
/** Water starts to slow a walk at this much of the body (about the knee). */
const WADE_FROM = 0.15
/** How much of the capsule stays out of the water afloat, as a part of the body's height. It
 *  puts the first-person eye just over the surface. */
const FLOAT_TOP = 0.2
// A dive: the feet this far over the surface (meters), water at least this many body heights
// deep, and the body moving forward at least this fast (meters per second). Slower, it drops in
// feet first.
const DIVE_CLEARANCE = 0.3
const DIVE_DEPTH = 1
const DIVE_SPEED = 1
/** A glide ends when the body has risen to this close under its floating height (meters). */
const SURFACED = 0.15
/** A body moving down slower than this is taken as at rest (meters per second). */
const SETTLING = 0.1
// Buoyancy as a spring to the floating height (1/s² and 1/s), a little under critical damping,
// so a body bobs once as it comes up. It pulls as if the body were no deeper than `PULL`
// (meters), so a deep plunge comes up at a swim, not a shot.
const BUOYANCY = 40
const DAMPING = 10
const PULL = 0.6
/** How far over its floating height the water still holds a body (meters). */
const BAND = 0.05
// Over a bed the water raises a body toward standing height at this rate (1/s), no faster than
// `CLIMB` (meters per second).
const RISE = 8
const CLIMB = 2.5
/** Hauling out over a wall is slower (meters per second): about a second from afloat to on top,
 *  time enough to see it done. */
const HAUL = 1.4
/** The highest ledge over the surface a swimmer is lifted onto (meters): a pool's rim, a low
 *  dock, a step. */
export const CLIMB_REACH = 0.6
/** A ledge is a wall to climb out onto, with a climb to show (`SwimState.climb`), when its top
 *  stands this far over the bed under the body (meters). Lower, it is a step or a bank, and the
 *  body is lifted up it on its feet. */
const WALL = 0.9
// A body held under takes up its speed down at the first rate, and comes to rest at standing
// height over the bed at the second (1/s): slow enough against the first that it settles there
// without bouncing.
const SINK = 6
const SETTLE = 2
// Water drag on the speed over the ground (1/s): while a direction is held, and the stronger one
// that ends a glide when none is.
const DRAG = 0.5
const DRAG_IDLE = 2.5
/** How fast the speed a dive carries in is shed (1/s). */
const SHED = 2.5

/** The avatar's capsule, as swimming needs it. Lengths in world units. */
export interface SwimShape {
  /** The feet below the capsule's centre: half the capsule and the height it floats off the
   *  ground. */
  feet: number
  /** The capsule's top above its centre. */
  top: number
  radius: number
  /** Feet to crown. */
  height: number
  unit: number
  /** Top speeds on land and in the water, walking and with the `run` key, in world units a
   *  second. */
  walk: number
  sprint: number
  swim: number
  swimSprint: number
}

/** The capsule this step. `stepSwim` changes its velocity in place. */
export interface SwimBody {
  /** Height of the capsule's centre. */
  y: number
  vx: number
  vy: number
  vz: number
}

/** What the capsule finds around it this step. */
export interface SwimSense {
  dt: number
  /** The still water over the body, or null where there is none. */
  level: number | null
  /** The swell on it now. */
  swell: number
  /** The ground under the body, `-Infinity` when none is in reach. */
  bed: number
  /** The ground just ahead of the body the way it is pushed, no higher than `CLIMB_REACH` over
   *  the surface; `-Infinity` when none, or nothing is pushed. */
  ahead: number
  /** Standing on something (the controller's ground test). */
  grounded: boolean
  /** A direction is held. */
  pushing: boolean
  /** The `run` key is held. */
  sprinting: boolean
  /** The `dive` control is held: swim down. */
  diving: boolean
}

/** What the water has the body doing. Climbing out is told apart from these (`SwimState.climb`):
 *  it starts as a swim and ends on dry feet. */
export type SwimPhase = Exclude<PlayerSwim, 'climb'>

export interface SwimState {
  phase: SwimPhase | null
  /** How much of the body is under the still water, 0 to 1. */
  immersion: number
  /** How far the body is under the height it rests at here (afloat, or standing on a bed that
   *  is higher), in world units. Negative over it: dropping in, climbing out. */
  submerged: number
  /** The height the water was taking the body to last step, to tell how fast it moves. */
  line: number | null
  /** Being lifted out onto a ledge ahead. */
  climbing: boolean
  /** While that ledge is a wall (a pool's rim, a dock, not a step or a bank): how far the feet
   *  still are under its top, in world units. Null otherwise. */
  climb: number | null
}

export const createSwimState = (): SwimState => ({
  phase: null,
  immersion: 0,
  submerged: 0,
  line: null,
  climbing: false,
  climb: null,
})

/** What a body in `state` is doing in water, as its motion says it (`PlayerMotion.swim`). */
export const swimming = (state: SwimState): PlayerSwim | null =>
  state.climb === null ? state.phase : 'climb'

/** How far under the height it is going to a body in `state` is (`PlayerMotion.submerged`). */
export const submersion = (state: SwimState) => state.climb ?? state.submerged

const clamp01 = (v: number) => Math.min(Math.max(v, 0), 1)
const smooth = (v: number) => v * v * (3 - 2 * v)

/** The height the capsule's centre floats at on water whose surface is at `surface`. */
export const floatLine = (shape: SwimShape, surface: number) =>
  surface + FLOAT_TOP * shape.height - shape.top

/** Which phase follows `state.phase`, given what the body finds this step and how far it is
 *  under the height it rests at. */
function nextPhase(
  state: SwimState,
  shape: SwimShape,
  body: SwimBody,
  sense: SwimSense,
  below: number,
): SwimPhase | null {
  const { level, grounded, diving } = sense
  if (level === null) return null
  const { height, unit } = shape
  const depth = level - sense.bed
  const clearance = body.y - shape.feet - level
  switch (state.phase) {
    case 'dive':
      if (grounded || depth < DIVE_DEPTH * height) return null
      return state.immersion > SWIM_AT ? 'glide' : 'dive'
    case 'glide':
      if (grounded && depth < STAND_AT * height) return null
      if (diving) return 'under'
      // Over once the body has gone under, turned, and come back up to where it floats.
      return body.vy >= 0 && below < SURFACED * unit ? 'swim' : 'glide'
    case 'under':
      if (depth < STAND_AT * height) return null
      // Held under for as long as the control is. Let go, it is over once the body is back up
      // where it floats and no longer on its way down: one resting on a pool's floor never
      // quite stops settling.
      return !diving && body.vy > -SETTLING * unit && below < SURFACED * unit ? 'swim' : 'under'
    case 'swim':
      if (depth < STAND_AT * height || state.immersion <= 0) return null
      return diving && !state.climbing ? 'under' : 'swim'
    default:
      // A body on its feet is judged by the water's depth, as it will be to stand again, so the
      // little its capsule settles can't flip it back and forth.
      if (state.immersion > SWIM_AT && (!grounded || depth > SWIM_AT * height)) return 'swim'
      return !grounded &&
        !state.climbing &&
        clearance >= DIVE_CLEARANCE * unit &&
        depth >= DIVE_DEPTH * height &&
        Math.hypot(body.vx, body.vz) >= DIVE_SPEED * unit
        ? 'dive'
        : null
  }
}

/**
 * One step of the avatar in water. Updates `state` (the phase, how much of the body is under,
 * how far it is below where it rests) and `body`'s velocity, and returns true when the water is
 * carrying the body this step, so gravity should be left out of it.
 *
 * From the knee up the water takes the body's weight. Afloat, a damped spring holds the capsule
 * at its floating height and follows the swell. Held under (`sense.diving`), it swims down at the
 * swimming speed as far as the bed, and floats back up when let go. Where the bed comes up under
 * it, or a ledge stands ahead of the way it is pushed, the water raises it to standing height
 * over that instead, so a swimmer gets up a bank too steep for the controller's ground spring, up
 * steps, and out onto a pool's rim or a low dock. Wading, the speed over the ground is held to a
 * cap that eases from the land speeds at the knee to the swimming speeds at the waist. Swimming,
 * drag ends a glide and the same cap holds the speed; what a dive carries in over it is shed
 * gradually.
 */
export function stepSwim(state: SwimState, shape: SwimShape, body: SwimBody, sense: SwimSense) {
  const { dt, level } = sense
  const { height, unit } = shape
  if (level === null) {
    state.phase = null
    state.immersion = 0
    state.submerged = 0
    state.line = null
    state.climbing = false
    state.climb = null
    return false
  }
  // Where the body rests here: afloat, or standing on a bed that is higher.
  const afloatAt = floatLine(shape, level + sense.swell)
  const rest = Math.max(afloatAt, sense.bed + shape.feet)
  state.immersion = clamp01((level - (body.y - shape.feet)) / height)
  state.phase = nextPhase(state, shape, body, sense, rest - body.y)
  const afloat = state.phase === 'swim' || state.phase === 'glide' || state.phase === 'under'
  state.submerged = afloat ? rest - body.y : 0

  // Where the water is taking it: there, or up onto what stands ahead of a body that swims or
  // wades into it. Once begun, a climb goes on out of the water until the ledge is underfoot.
  const ledge = sense.ahead + shape.feet
  const wet = state.phase === 'swim' || (state.phase === null && state.immersion > WADE_FROM)
  state.climbing = ledge > rest && (state.climbing || wet)
  const line = state.climbing ? ledge : rest
  const below = line - body.y
  // A wall out of the water is a climb to show, from when it starts until it is underfoot.
  const wall = sense.ahead >= level && sense.ahead - sense.bed >= WALL * unit
  state.climb = state.climbing && (state.climb !== null || wall) ? Math.max(below, 0) : null
  let carried = false
  if (state.phase === 'under' && sense.diving) {
    // Down at the swimming speed, easing to a stop at standing height over the bed.
    const most = sense.sprinting ? shape.swimSprint : shape.swim
    const room = body.y - (sense.bed + shape.feet)
    const down = Math.min(most, SETTLE * room)
    body.vy += (-down - body.vy) * (1 - Math.exp(-SINK * dt))
    carried = true
  } else if ((afloat || state.climbing || state.immersion > WADE_FROM) && below > -BAND * unit) {
    // How fast that height is itself moving (a swell, a bank coming up under a swimmer), fed
    // forward so the body keeps up with it.
    const rate = state.line === null || dt <= 0 ? 0 : (line - state.line) / dt
    const moving = Math.min(Math.max(rate, -2 * unit), 2 * unit)
    if (line > afloatAt) {
      const most = state.climb === null ? CLIMB : HAUL
      const rise = Math.min(RISE * below + Math.max(moving, 0), most * unit)
      // A climb is taken up at just that speed, so it arrives without overshooting. Over a bed
      // the water only lifts: holding a body down to it would keep it off a step.
      body.vy = state.climbing ? Math.max(rise, 0) : Math.max(body.vy, rise)
    } else {
      const pull = Math.min(below, PULL * unit)
      body.vy += (BUOYANCY * pull - DAMPING * (body.vy - moving)) * dt
    }
    carried = true
  }
  state.line = line

  // Water drags at a body on its feet, not at one falling through the surface.
  const wading = sense.grounded
    ? smooth(clamp01((state.immersion - WADE_FROM) / (SWIM_AT - WADE_FROM)))
    : 0
  if (!afloat && wading <= 0) return carried

  if (afloat && !sense.grounded) {
    const drag = Math.exp(-(sense.pushing ? DRAG : DRAG_IDLE) * dt)
    body.vx *= drag
    body.vz *= drag
  }
  const land = sense.sprinting ? shape.sprint : shape.walk
  const water = sense.sprinting ? shape.swimSprint : shape.swim
  const most = afloat ? water : land + (Math.min(water, land) - land) * wading
  const speed = Math.hypot(body.vx, body.vz)
  if (speed > most) {
    const kept = state.phase === 'glide' ? most + (speed - most) * Math.exp(-SHED * dt) : most
    body.vx *= kept / speed
    body.vz *= kept / speed
  }
  return carried
}

import { useFrame, useThree } from '@react-three/fiber'
import { DYNAMIC_KEY, skipMirrors, useWorld, type WaterSample, waterAt } from '@runek/core'
import { useEffect, useState } from 'react'
import {
  AdditiveBlending,
  Color,
  DataTexture,
  DoubleSide,
  InstancedMesh,
  LinearFilter,
  MeshBasicMaterial,
  Object3D,
  PlaneGeometry,
  RGBAFormat,
} from 'three'
import { createWake, dropAt, type Mark, ringAt, stepWake, type WakeBody } from './wake'

/** White falling off from `peak` to nothing `width` either side of it, drawn in code: at 0 a
 *  soft round dot, further out a ring. Across a square, `r` runs 0 in the middle to 1 at an edge. */
function glowTexture(peak: number, width: number): DataTexture {
  const N = 64
  const data = new Uint8Array(N * N * 4)
  for (let y = 0; y < N; y++) {
    for (let x = 0; x < N; x++) {
      const r = Math.hypot(x - (N - 1) / 2, y - (N - 1) / 2) / (N / 2)
      const a = Math.max(0, 1 - Math.abs(r - peak) / width)
      const v = Math.round(255 * a * a * (3 - 2 * a))
      data.set([v, v, v, 255], (y * N + x) * 4)
    }
  }
  const texture = new DataTexture(data, N, N, RGBAFormat)
  texture.magFilter = texture.minFilter = LinearFilter
  texture.needsUpdate = true
  return texture
}

let ringMap: DataTexture | null = null
let dropMap: DataTexture | null = null

/** Light added over the water: nothing where the texture is black, and it never darkens. */
const glow = (map: DataTexture) =>
  new MeshBasicMaterial({
    map,
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
    fog: false,
    side: DoubleSide,
  })

// Foam: a little blue in the white. How bright a ring and a drop are at their brightest.
const FOAM = '#dcefff'
const RING_GLOW = 0.42
const DROP_GLOW = 0.8
/** How far over the water a ring is drawn, in meters, so the surface doesn't cut through it. */
const OVER = 0.03

/**
 * The rings and splashes a body leaves on water (see `water/wake.ts`), for whoever says where
 * that body is: `Player` for its avatar, `Person` for a figure on its own. `source` is read
 * every frame.
 *
 * Two instanced draws, of light added over the water, in world space, so the rings stay where
 * they were left as the body moves on: rings lying on the surface, each at the height the water
 * has there now, and drops facing the camera. Neither is drawn while it has nothing to show, and
 * both are left out of mirrors.
 */
export function WaterTrail({ source, seed = 1 }: { source: { current: WakeBody }; seed?: number }) {
  const scene = useThree((three) => three.scene)
  const { waters, unit } = useWorld()
  const [v] = useState(() => {
    const wake = createWake(seed)
    ringMap ??= glowTexture(0.86, 0.11)
    dropMap ??= glowTexture(0, 1)
    const flat = new PlaneGeometry(2, 2).rotateX(-Math.PI / 2)
    const rings = new InstancedMesh(flat, glow(ringMap), wake.rings.length)
    const drops = new InstancedMesh(new PlaneGeometry(1, 1), glow(dropMap), wake.drops.length)
    for (const mesh of [rings, drops]) {
      mesh.visible = false
      mesh.frustumCulled = false
      // After the water it lies on, which would otherwise be drawn over it.
      mesh.renderOrder = 1
      mesh.userData[DYNAMIC_KEY] = true
    }
    return {
      wake,
      rings,
      drops,
      at: new Object3D(),
      mark: { x: 0, y: 0, z: 0, size: 0, glow: 0 } as Mark,
      sample: { level: 0, swell: 0 } as WaterSample,
      foam: new Color(FOAM),
      tint: new Color(),
    }
  })

  useEffect(() => {
    const { rings, drops } = v
    scene.add(rings, drops)
    const mirrored = [skipMirrors(rings), skipMirrors(drops)]
    return () => {
      for (const restore of mirrored) restore()
      scene.remove(rings, drops)
    }
  }, [scene, v])
  useEffect(
    () => () => {
      for (const mesh of [v.rings, v.drops]) {
        mesh.geometry.dispose()
        mesh.material.dispose()
        mesh.dispose()
      }
    },
    [v],
  )

  useFrame(({ camera }, delta) => {
    const { wake, rings, drops, at, mark, tint, foam } = v
    const body = source.current
    stepWake(wake, body, Math.min(delta, 0.1), unit)

    let shown = 0
    at.quaternion.identity()
    for (const ring of wake.rings) {
      if (!ringAt(ring, wake.time, unit, mark)) continue
      // Where the water stands under the ring now: it rides the swell it was left on.
      const water = waterAt(waters, mark.x, body.y + unit, mark.z, v.sample)
      if (!water) continue
      at.position.set(mark.x, water.level + water.swell + OVER * unit, mark.z)
      at.scale.setScalar(mark.size)
      at.updateMatrix()
      rings.setMatrixAt(shown, at.matrix)
      rings.setColorAt(shown, tint.copy(foam).multiplyScalar(mark.glow * RING_GLOW))
      shown++
    }
    show(rings, shown)

    shown = 0
    at.quaternion.copy(camera.quaternion)
    for (const drop of wake.drops) {
      if (!dropAt(drop, wake.time, unit, mark)) continue
      at.position.set(mark.x, mark.y, mark.z)
      at.scale.setScalar(mark.size)
      at.updateMatrix()
      drops.setMatrixAt(shown, at.matrix)
      drops.setColorAt(shown, tint.copy(foam).multiplyScalar(mark.glow * DROP_GLOW))
      shown++
    }
    show(drops, shown)
  })
  return null
}

/** Draw the first `count` instances of `mesh`, or none of it. */
function show(mesh: InstancedMesh, count: number) {
  mesh.count = count
  mesh.visible = count > 0
  if (!count) return
  mesh.instanceMatrix.needsUpdate = true
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true
}

// The marks a body leaves on water: rings that spread from where it is and where it was (a line
// of them behind a swimmer opens into a wake), and the splash of going in. Plain numbers, kept in
// two fixed pools, so it is tested without a scene; `water/trail.tsx` draws them.
import { rng } from '@runek/core'

// Lengths in meters, times in seconds.
/** How long a ring lasts. */
const RING_LIFE = 2.4
/** A ring's radius as it is left, and how fast it spreads: a trail's, then a splash's. */
const RING_START = 0.18
const SPREAD = 0.5
const SPLASH_SPREAD = 1.1
/** A swimmer leaves a ring every this far, */
const SPACING = 0.5
/** and a body that stays where it is, one every this long. */
const IDLE = 1.1
// Going into the water slower than the first is a ripple; from the second up it is the biggest
// splash there is (about a fall of two meters).
const GENTLE = 1
const HARD = 6
const DROP_LIFE = 1.2
const GRAVITY = 9.81

/** One ring on the water. */
export interface Ring {
  /** Where its middle is, in world coordinates. */
  x: number
  z: number
  /** When it was left, on the wake's clock; `Infinity` for one never used. */
  born: number
  /** How bright it starts, 0 to 1. */
  strength: number
  /** How fast it spreads, in meters a second. */
  spread: number
}

/** One drop thrown up by a splash. */
export interface Drop {
  x: number
  /** The water's surface where it was thrown up from. */
  y: number
  z: number
  vx: number
  vy: number
  vz: number
  born: number
  /** Across, in meters. */
  size: number
}

/** A body as its wake needs it this step. */
export interface WakeBody {
  /** In the water and breaking its surface: wading, afloat, climbing out. Not while it is
   *  wholly under. */
  wet: boolean
  /** Where it is, in world coordinates; `y` is the water's surface there. */
  x: number
  y: number
  z: number
  /** How fast it is falling, in world units a second: what a splash is sized by as it goes in. */
  fall: number
}

export interface Wake {
  rings: Ring[]
  drops: Drop[]
  /** Seconds this wake has run. */
  time: number
  /** The slot the next ring, and the next drop, goes in. */
  ring: number
  drop: number
  /** In the water last step, and where it left its last ring, how long ago. */
  wet: boolean
  x: number
  z: number
  since: number
  random: () => number
}

/** An empty wake. `seed` sets how each splash scatters; the pools hold as many rings and drops
 *  as can show at once, and the oldest are written over. */
export function createWake(seed: number, rings = 24, drops = 18): Wake {
  return {
    rings: Array.from({ length: rings }, () => ({
      x: 0,
      z: 0,
      born: Number.POSITIVE_INFINITY,
      strength: 0,
      spread: SPREAD,
    })),
    drops: Array.from({ length: drops }, () => ({
      x: 0,
      y: 0,
      z: 0,
      vx: 0,
      vy: 0,
      vz: 0,
      born: Number.POSITIVE_INFINITY,
      size: 0,
    })),
    time: 0,
    ring: 0,
    drop: 0,
    wet: false,
    x: 0,
    z: 0,
    since: 0,
    random: rng(seed),
  }
}

const clamp01 = (v: number) => Math.min(Math.max(v, 0), 1)
const smooth = (v: number) => {
  const c = clamp01(v)
  return c * c * (3 - 2 * c)
}

function ring(wake: Wake, body: WakeBody, strength: number, spread = SPREAD, delay = 0) {
  const next = wake.rings[wake.ring]
  wake.ring = (wake.ring + 1) % wake.rings.length
  next.x = body.x
  next.z = body.z
  next.born = wake.time + delay
  next.strength = strength
  next.spread = spread
  wake.x = body.x
  wake.z = body.z
  wake.since = 0
}

/** Going in: a ripple at a walk, and from a fall rings that spread fast and drops thrown up and
 *  out, more of both the harder it lands. */
function splash(wake: Wake, body: WakeBody, unit: number) {
  const hit = clamp01((body.fall / unit - GENTLE) / (HARD - GENTLE))
  if (hit <= 0) return ring(wake, body, 0.5)
  ring(wake, body, 0.6 + 0.4 * hit, SPLASH_SPREAD)
  ring(wake, body, 0.45 + 0.3 * hit, SPLASH_SPREAD, 0.14)
  ring(wake, body, 0.3 + 0.2 * hit, SPREAD, 0.3)
  const { drops, random } = wake
  const count = Math.round(4 + (drops.length - 4) * hit)
  for (let i = 0; i < count; i++) {
    const drop = drops[wake.drop]
    wake.drop = (wake.drop + 1) % drops.length
    const turn = random() * Math.PI * 2
    const out = (0.4 + 1.4 * random()) * (0.5 + 0.5 * hit) * unit
    drop.x = body.x + Math.cos(turn) * 0.15 * unit
    drop.y = body.y
    drop.z = body.z + Math.sin(turn) * 0.15 * unit
    drop.vx = Math.cos(turn) * out
    drop.vy = (1.6 + 2.6 * random()) * (0.6 + 0.4 * hit) * unit
    drop.vz = Math.sin(turn) * out
    drop.born = wake.time + 0.06 * random()
    drop.size = (0.035 + 0.05 * random()) * unit
  }
}

/**
 * One step of a wake, `dt` seconds on: leaves the rings and drops `body` makes this step. Going
 * into the water is a splash sized by how fast it falls; moving through it leaves a ring every
 * half meter, brighter the faster it goes; staying put, a faint one now and then; coming out of
 * it, or back up to the surface, one more.
 */
export function stepWake(wake: Wake, body: WakeBody, dt: number, unit = 1) {
  wake.time += dt
  const was = wake.wet
  wake.wet = body.wet
  if (!body.wet) {
    if (was) ring(wake, { ...body, x: wake.x, z: wake.z }, 0.4)
    return
  }
  if (!was) return splash(wake, body, unit)
  wake.since += dt
  const moved = Math.hypot(body.x - wake.x, body.z - wake.z)
  if (moved >= SPACING * unit) {
    // Its speed since the last ring; a jump (a teleport) is no faster than a sprint.
    const speed = Math.min(moved / Math.max(wake.since, dt), 3 * unit)
    ring(wake, body, 0.3 + 0.5 * clamp01(speed / (2.6 * unit)))
  } else if (wake.since >= IDLE) ring(wake, body, 0.28)
}

/** What a ring or a drop looks like now. */
export interface Mark {
  x: number
  y: number
  z: number
  /** A ring's radius, or a drop's width, in world units. */
  size: number
  /** How bright, 0 to 1. */
  glow: number
}

/** A ring `at` the wake's time: how wide it has spread and how far it has faded. False once it is
 *  gone, or before a ring left with a delay has begun. Writes `x`, `z`, `size` and `glow`. */
export function ringAt(ring: Ring, at: number, unit: number, out: Mark): boolean {
  const age = at - ring.born
  if (!(age >= 0 && age < RING_LIFE)) return false
  out.x = ring.x
  out.z = ring.z
  out.size = (RING_START + ring.spread * age) * unit
  out.glow = ring.strength * smooth(age / 0.2) * (1 - age / RING_LIFE) ** 2
  return true
}

/** A drop `at` the wake's time: up, over and back down. False once it has fallen back in. */
export function dropAt(drop: Drop, at: number, unit: number, out: Mark): boolean {
  const age = at - drop.born
  if (!(age >= 0 && age < DROP_LIFE)) return false
  const y = drop.vy * age - 0.5 * GRAVITY * unit * age * age
  if (y < 0) return false
  out.x = drop.x + drop.vx * age
  out.y = drop.y + y
  out.z = drop.z + drop.vz * age
  out.size = drop.size
  out.glow = 1 - 0.6 * (age / DROP_LIFE)
  return true
}

import type { Matrix4, Texture, Vector2 } from 'three'
import {
  asin,
  atan,
  cos,
  Fn,
  float,
  If,
  length,
  positionGeometry,
  sin,
  smoothstep,
  sqrt,
  texture,
  uniform,
  uv,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { follow } from './uniforms'

type F = Node<'float'>
type V2 = Node<'vec2'>
type V3 = Node<'vec3'>
type V4 = Node<'vec4'>

export interface LensUniforms {
  uAhead: { value: Texture }
  uLeft: { value: Texture }
  uRight: { value: Texture }
  uAheadM: { value: Matrix4 }
  uLeftM: { value: Matrix4 }
  uRightM: { value: Matrix4 }
  uExtent: { value: Vector2 }
  uResolution: { value: Vector2 }
  uBlur: { value: number }
  uSeam: { value: number }
}

/**
 * The node (TSL) twin of the first-person lens's stitching pass, for `WebGPURenderer`: warps the
 * views into the Panini curve and blurs the periphery. `focus` is the falloff ellipse (radians
 * across and up, and where it starts and ends).
 */
export function lensPassMaterial(
  record: LensUniforms,
  curve: number,
  focus: { across: number; up: number; from: number; to: number },
) {
  const extent = follow<V2>(record.uExtent)
  const resolution = follow<V2>(record.uResolution)
  const blur = follow<F>(record.uBlur)
  const seam = follow<F>(record.uSeam)
  const views = (['Ahead', 'Left', 'Right'] as const).map((name) => ({
    map: record[`u${name}`].value,
    m: uniform(record[`u${name}M`].value),
  }))

  const project = (m: Node<'mat4'>, dir: V3) => {
    const c = m.mul(vec4(dir, 1))
    return c.xy.div(c.w).mul(0.5).add(0.5) as V2
  }
  // The direction seen at a point on the screen, one unit out from the eye's vertical axis.
  const ray = (at: V2) => {
    const p = at.mul(2).sub(1).mul(extent) as V2
    const k = p.x.div(curve + 1)
    const phi = atan(k).add(asin(k.mul(curve).div(sqrt(k.mul(k).add(1)))))
    return vec3(sin(phi), p.y.mul(cos(phi).add(curve)).div(curve + 1), cos(phi).negate()) as V3
  }
  // WebGPU render targets run top-down: flip the WebGL-style coordinates, and their y gradients.
  const flip = (p: V2) => vec2(p.x, p.y.oneMinus())
  const down = (g: V2) => vec2(g.x, g.y.negate())

  const look = (view: (typeof views)[number], dir: V3, nx: V3, ny: V3, sigma: F, out: V4) => {
    const at = project(view.m as unknown as Node<'mat4'>, dir)
    If(sigma.lessThan(0.35), () => {
      out.assign(texture(view.map, flip(at)).level(float(0)))
    }).Else(() => {
      const gx = project(view.m as unknown as Node<'mat4'>, nx)
        .sub(at)
        .mul(sigma) as V2
      const gy = project(view.m as unknown as Node<'mat4'>, ny)
        .sub(at)
        .mul(sigma) as V2
      const tap = (a: number, b: number) =>
        texture(view.map, flip(at.add(gx.mul(a)).add(gy.mul(b)) as V2)).grad(down(gx), down(gy))
      out.assign(
        tap(0.7, 0.28).add(tap(-0.28, 0.7)).add(tap(-0.7, -0.28)).add(tap(0.28, -0.7)).mul(0.25),
      )
    })
  }

  const shade = Fn(() => {
    const at = uv() as V2
    const dir = ray(at)
    const phi = atan(dir.x, dir.z.negate()) as F
    const off = vec2(phi.div(focus.across), atan(dir.y).div(focus.up))
    const sigma = blur.mul(smoothstep(focus.from, focus.to, length(off))) as F
    const nx = ray(at.add(vec2(float(1).div(resolution.x), 0)) as V2)
    const ny = ray(at.add(vec2(0, float(1).div(resolution.y))) as V2)
    const color = vec4(0).toVar() as unknown as V4
    If(phi.greaterThan(seam), () => look(views[2], dir, nx, ny, sigma, color))
      .ElseIf(phi.lessThan(seam.negate()), () => look(views[1], dir, nx, ny, sigma, color))
      .Else(() => look(views[0], dir, nx, ny, sigma, color))
    return color
  })

  const material = new MeshBasicNodeMaterial({ depthTest: false, depthWrite: false })
  material.vertexNode = vec4(positionGeometry.xy, 0, 1)
  // The views hold linear light; the frame's output pass tone-maps and encodes it once.
  material.colorNode = shade()
  return material
}

import { float, uniform } from 'three/tsl'
import { Node, type NodeFrame, NodeUpdateType } from 'three/webgpu'

/** A TSL uniform that follows `entry.value` every render, so the `{ value }` records a
 *  component already updates (for its GLSL material) drive its node material too. */
export function follow<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onRenderUpdate(() => entry.value as never) as unknown as N
}

class BeforeDraw extends Node {
  constructor(private readonly run: (frame: NodeFrame) => void) {
    super('float')
    this.updateBeforeType = NodeUpdateType.OBJECT
  }

  updateBefore(frame: NodeFrame) {
    this.run(frame)
    return true
  }

  setup() {
    return float(0)
  }
}

/**
 * A node worth 0 that runs `run` before each object using it draws: add it to anything in the
 * material to have it run. For what a uniform can't do per object, like pointing a texture node at
 * another texture (a texture node resets its own update hook when it builds).
 */
export function beforeDraw(run: (frame: NodeFrame) => void): Node<'float'> {
  return new BeforeDraw(run) as unknown as Node<'float'>
}
